{"command": "cd /workspace/work && for args in '{"path":"/workspace/work/r_loops1.wav","loops":1}' '{"path":"/workspace/work/r_start_stop.wav","loops":1,"start":0,"stop":1}' '{"path":"/workspace/work/r_amp.wav","loops":1,"amp":200}'; do echo "== $args"; ft2 call module_render "$args" 2>&1 | head -c 500; echo; done; python3 - <<'EOF'
import wave, numpy as np
for f in ['r_loops1','r_start_stop','r_amp']:
    try:
        w=wave.open(f'/workspace/work/{f}.wav','rb')
    except Exception as e:
        print(f,e); continue
    x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float)/32768
    print(f,'ch',w.getnchannels(),'rate',w.getframerate(),'dur',round(w.getnframes()/w.getframerate(),3),'peak',round(np.abs(x).max(),4))
EOF"}

